input.command:
cd /tmp/png-agent && for f in "" "-S" "-A" "-A -S"; do out="line$(echo $f|tr -d ' -' )".png; /workspace/executable line.txt $out $f >/dev/null 2>&1; echo "--- args='$f' -> $out"; python3 - "$out" <<'EOF'
import sys; sys.path.insert(0,'/workspace/tools')
from pngread import pixels
w,h,px,ct=pixels(sys.argv[1])
print(" size",w,h,"ct",ct)
print(" corners:",px[0][0],px[0][w-1],px[h-1][0],px[h-1][w-1])
vals={}
for y in range(h):
    for x in range(w):
        vals[px[y][x]]=vals.get(px[y][x],0)+1
for k,v in sorted(vals.items(),key=lambda kv:-kv[1])[:12]: print("  ",k,v)
print(" row35:",[px[35][x][0] for x in range(20,32)])
EOF
done
